const response = items[0]?.json ?? {};
const meetingData = response.data ?? {};
const speakersRaw = Array.isArray(meetingData.speakers) ? meetingData.speakers : [];

const speakers = [...new Set(
  speakersRaw
    .map(speaker => speaker?.name)
    .filter(name => typeof name === 'string' && name.trim() !== '')
)];

return [
  {
    json: {
      speakers,
      speakersText: speakers.join(', ')
    }
  }
];

const response = items[0]?.json ?? {};
const meetingData = response.data ?? {};

const sentences = Array.isArray(meetingData.sentences) ? meetingData.sentences : [];
const speakersRaw = Array.isArray(meetingData.speakers) ? meetingData.speakers : [];

let transcript = '';
let lastSpeaker = null;

for (const sentence of sentences) {
  const speakerName =
    sentence?.speaker_name?.trim() ||
    (sentence?.speaker_id !== undefined && sentence?.speaker_id !== null
      ? `Speaker ${sentence.speaker_id}`
      : 'Unknown Speaker');

  const text =
    sentence?.ai_filters?.text_cleanup?.trim() ||
    sentence?.text?.trim() ||
    sentence?.raw_text?.trim() ||
    '';

  if (!text) continue;

  if (speakerName !== lastSpeaker) {
    if (transcript) transcript += '\n\n';
    transcript += `${speakerName}:\n`;
    lastSpeaker = speakerName;
  }

  transcript += `${text} `;
}

const speakers = [
  ...new Set(
    speakersRaw
      .map(speaker => speaker?.name?.trim())
      .filter(name => typeof name === 'string' && name !== '')
  )
];

return [
  {
    json: {
      transcript: transcript.trim(),
      speakers,
      speakersText: speakers.join(', '),
      speakerCount: speakers.length
    }
  }
];

const raw = items[0]?.json ?? {};

const CANVAS = {
  w: 720,
  h: 405,
  unit: 'PT',
};

const FONT = 'Arial';

const COLORS = {
  bg: '#F8FAFC',
  dark: '#0F172A',
  navy: '#1E3A8A',
  blue: '#2563EB',
  lightBlue: '#EAF2FF',
  paleBlue: '#DBEAFE',
  slate: '#334155',
  gray: '#64748B',
  lightGray: '#F1F5F9',
  border: '#CBD5E1',
  white: '#FFFFFF',
  green: '#ECFDF5',
  orange: '#FFF7ED',
  red: '#FEF2F2',
};

const BLOCKED_PLACEHOLDER_PHRASES = [
  'confirm the missing detail',
  'specific detail was not fully defined',
  'follow-up area',
  'key discussion point',
  'referenced in the meeting discussion',
  'this point requires follow-up based on the meeting discussion',
  'clarify the next decision, owner, or success signal',
  'follow up on this meeting topic with clearer ownership',
  'completion evidence confirmed for',
];

const BLOCKED_PLACEHOLDER_HEADINGS = [
  'leadership takeaway',
  'risk implication',
  'define success metrics',
  'maintain review cadence',
  'decision tradeoff',
  'follow-up focus',
  'strategic option',
  'priority area',
  'primary ambiguity',
  'execution blocker',
  'decision tension',
];

function cleanJsonString(value) {
  let text = String(value ?? '').trim();

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');

  if (first >= 0 && last > first) {
    text = text.slice(first, last + 1);
  }

  return text;
}

function extractDeck(input) {
  let candidate = input;

  if (candidate && typeof candidate === 'object' && candidate.output !== undefined) {
    candidate = candidate.output;
  }

  if (Array.isArray(candidate)) {
    candidate = candidate
      .map((item) => {
        if (typeof item === 'string') return item;
        if (item?.text) return item.text;
        if (item?.output) return item.output;
        if (item?.json?.output) return item.json.output;
        return '';
      })
      .filter(Boolean)
      .join('\n');
  }

  if (typeof candidate === 'string') {
    return JSON.parse(cleanJsonString(candidate));
  }

  if (candidate && typeof candidate === 'object') {
    return candidate;
  }

  throw new Error('Cannot extract valid deck JSON from AI Agent output.');
}

function safeText(value) {
  if (value === null || value === undefined) return '';

  if (typeof value === 'object') {
    const candidates = [
      value.text,
      value.title,
      value.heading,
      value.theme,
      value.summary,
      value.body,
      value.recommendation,
      value.action,
      value.successSignal,
      value.evidence,
      value.implication,
    ];

    const first = candidates.find((item) => typeof item === 'string' && item.trim());
    if (first) {
      return String(first).replace(/\r?\n|\r/g, ' ').replace(/\s+/g, ' ').trim();
    }

    return '';
  }

  return String(value)
    .replace(/\r?\n|\r/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function clamp(value, fallback, min, max) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(Math.max(n, min), max);
}

function isBlockedPhrase(value) {
  const text = safeText(value).toLowerCase();
  if (!text) return false;
  return BLOCKED_PLACEHOLDER_PHRASES.some((phrase) => text.includes(phrase));
}

function isBlockedHeading(value) {
  const text = safeText(value).toLowerCase();
  if (!text) return false;
  return BLOCKED_PLACEHOLDER_HEADINGS.some((phrase) => text === phrase || text.includes(phrase));
}

function cleanText(value) {
  const text = safeText(value);
  if (!text) return '';
  if (isBlockedPhrase(text)) return '';
  return text;
}

function clipText(value, max = 160) {
  const text = cleanText(value);
  if (text.length <= max) return text;
  return text.slice(0, max - 1).trim() + '…';
}

function wordsFrom(text, count = 6) {
  return safeText(text)
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, count)
    .join(' ');
}

function normalizeHex(hex, fallback = '#FFFFFF') {
  if (!hex || typeof hex !== 'string') return fallback;

  const value = hex.trim();

  if (value.toLowerCase() === 'transparent') return 'transparent';

  if (/^#[0-9A-Fa-f]{6}$/.test(value)) return value;

  if (/^#[0-9A-Fa-f]{3}$/.test(value)) {
    return `#${value[1]}${value[1]}${value[2]}${value[2]}${value[3]}${value[3]}`;
  }

  return fallback;
}

function hexToRgb(hex, fallback = '#FFFFFF') {
  const normalized = normalizeHex(hex, fallback);

  if (normalized === 'transparent') {
    return { red: 1, green: 1, blue: 1 };
  }

  const raw = normalized.replace('#', '');
  const intValue = parseInt(raw, 16);

  return {
    red: ((intValue >> 16) & 255) / 255,
    green: ((intValue >> 8) & 255) / 255,
    blue: (intValue & 255) / 255,
  };
}

function id(prefix, slideIndex, itemIndex = 0) {
  return `${prefix}_${String(slideIndex + 1).padStart(2, '0')}_${String(itemIndex + 1).padStart(3, '0')}`;
}

function push(requests, request) {
  if (request) requests.push(request);
}

function createSlide(slideId, insertionIndex) {
  return {
    createSlide: {
      objectId: slideId,
      insertionIndex,
      slideLayoutReference: {
        predefinedLayout: 'BLANK',
      },
    },
  };
}

function createShape(slideId, objectId, shapeType, x, y, w, h) {
  return {
    createShape: {
      objectId,
      shapeType,
      elementProperties: {
        pageObjectId: slideId,
        size: {
          width: { magnitude: w, unit: 'PT' },
          height: { magnitude: h, unit: 'PT' },
        },
        transform: {
          scaleX: 1,
          scaleY: 1,
          translateX: x,
          translateY: y,
          unit: 'PT',
        },
      },
    },
  };
}

function updateFill(objectId, fillColor = 'transparent', opacity = 1) {
  const color = normalizeHex(fillColor, 'transparent');
  const alpha = color === 'transparent' ? 0 : clamp(opacity, 1, 0, 1);

  return {
    updateShapeProperties: {
      objectId,
      shapeProperties: {
        shapeBackgroundFill: {
          solidFill: {
            color: {
              rgbColor: hexToRgb(color, '#FFFFFF'),
            },
            alpha,
          },
        },
      },
      fields: 'shapeBackgroundFill.solidFill.color,shapeBackgroundFill.solidFill.alpha',
    },
  };
}

function updateOutline(objectId, borderColor = 'transparent', borderWeight = 0) {
  const color = normalizeHex(borderColor, 'transparent');
  const weight = clamp(borderWeight, 0, 0, 10);

  if (color === 'transparent' || weight <= 0) {
    return {
      updateShapeProperties: {
        objectId,
        shapeProperties: {
          outline: {
            propertyState: 'NOT_RENDERED',
          },
        },
        fields: 'outline.propertyState',
      },
    };
  }

  return {
    updateShapeProperties: {
      objectId,
      shapeProperties: {
        outline: {
          outlineFill: {
            solidFill: {
              color: {
                rgbColor: hexToRgb(color, COLORS.border),
              },
              alpha: 1,
            },
          },
          weight: {
            magnitude: weight,
            unit: 'PT',
          },
        },
      },
      fields: 'outline.outlineFill.solidFill.color,outline.outlineFill.solidFill.alpha,outline.weight',
    },
  };
}

function insertText(objectId, text) {
  return {
    insertText: {
      objectId,
      insertionIndex: 0,
      text: safeText(text) || ' ',
    },
  };
}

function updateTextStyle(objectId, options = {}) {
  const fontSize = clamp(options.fontSize, 10, 6, 34);
  const color = normalizeHex(options.color, COLORS.dark);

  return {
    updateTextStyle: {
      objectId,
      textRange: {
        type: 'ALL',
      },
      style: {
        fontSize: {
          magnitude: fontSize,
          unit: 'PT',
        },
        bold: Boolean(options.bold),
        italic: Boolean(options.italic),
        foregroundColor: {
          opaqueColor: {
            rgbColor: hexToRgb(color, COLORS.dark),
          },
        },
        weightedFontFamily: {
          fontFamily: options.fontFamily || FONT,
        },
      },
      fields: 'fontSize,bold,italic,foregroundColor,weightedFontFamily',
    },
  };
}

function updateParagraph(objectId, options = {}) {
  return {
    updateParagraphStyle: {
      objectId,
      textRange: {
        type: 'ALL',
      },
      style: {
        alignment: options.align || 'START',
        lineSpacing: clamp(options.lineSpacing, 105, 85, 150),
      },
      fields: 'alignment,lineSpacing',
    },
  };
}

function updateVerticalAlign(objectId, valign = 'TOP') {
  return {
    updateShapeProperties: {
      objectId,
      shapeProperties: {
        contentAlignment: valign,
      },
      fields: 'contentAlignment',
    },
  };
}

function addRect(requests, slideId, objectId, x, y, w, h, options = {}) {
  push(requests, createShape(slideId, objectId, options.shapeType || 'RECTANGLE', x, y, w, h));
  push(requests, updateFill(objectId, options.fillColor || COLORS.white, options.opacity ?? 1));
  push(requests, updateOutline(objectId, options.borderColor || 'transparent', options.borderWeight || 0));
}

function addText(requests, slideId, objectId, x, y, w, h, text, options = {}) {
  const cleaned = cleanText(text);
  if (!cleaned && options.skipIfEmpty) return;

  push(requests, createShape(slideId, objectId, 'TEXT_BOX', x, y, w, h));
  push(requests, updateFill(objectId, options.fillColor || 'transparent', options.opacity ?? 0));
  push(requests, updateOutline(objectId, options.borderColor || 'transparent', options.borderWeight || 0));
  push(requests, insertText(objectId, cleaned || ' '));
  push(requests, updateTextStyle(objectId, options));
  push(requests, updateParagraph(objectId, options));
  push(requests, updateVerticalAlign(objectId, options.valign || 'TOP'));
}

function fontFor(text, base = 9, min = 7) {
  const len = safeText(text).length;

  if (len > 850) return min;
  if (len > 720) return Math.max(min, base - 2);
  if (len > 620) return Math.max(min, base - 1.8);
  if (len > 500) return Math.max(min, base - 1.3);
  if (len > 380) return Math.max(min, base - 0.9);
  if (len > 260) return Math.max(min, base - 0.4);

  return base;
}

function makeSection(heading, body, evidence = '', implication = '') {
  const cleanBody = cleanText(body);
  const cleanEvidence = cleanText(evidence);
  const cleanImplication = cleanText(implication);

  let cleanHeading = cleanText(heading);

  if (isBlockedHeading(cleanHeading)) {
    cleanHeading = '';
  }

  if (!cleanHeading && cleanBody) {
    cleanHeading = wordsFrom(cleanBody, 6) || 'Core insight';
  }

  return {
    heading: cleanHeading,
    body: cleanBody,
    evidence: cleanEvidence,
    implication: cleanImplication,
  };
}

function isValidSection(section) {
  if (!section) return false;

  const hasHeading = Boolean(cleanText(section.heading));
  const hasBody = Boolean(cleanText(section.body));
  const hasEvidence = Boolean(cleanText(section.evidence));
  const hasImplication = Boolean(cleanText(section.implication));

  return hasHeading && (hasBody || hasEvidence || hasImplication);
}

function getRawSections(slide) {
  const sections = Array.isArray(slide.sections) ? slide.sections : [];

  const cleaned = sections
    .map((s) =>
      makeSection(
        s?.heading,
        s?.body,
        s?.evidence,
        s?.implication
      )
    )
    .filter(isValidSection);

  if (cleaned.length > 0) {
    return cleaned;
  }

  const keyMessage = cleanText(slide.keyMessage);
  const callout = cleanText(slide.callout);

  if (keyMessage || callout) {
    return [
      makeSection(
        'Core takeaway',
        keyMessage || callout,
        '',
        callout && callout !== keyMessage ? callout : ''
      ),
    ];
  }

  return [];
}

function getSections(slide, min = 0, max = 5) {
  return getRawSections(slide).slice(0, max);
}

function sectionText(section, mode = 'full') {
  const body = cleanText(section.body);
  const evidence = cleanText(section.evidence);
  const implication = cleanText(section.implication);

  if (mode === 'compact') {
    return [
      body,
      implication ? `Implication: ${implication}` : '',
    ]
      .filter(Boolean)
      .join('\n\n');
  }

  return [
    body,
    evidence ? `Evidence: ${evidence}` : '',
    implication ? `Implication: ${implication}` : '',
  ]
    .filter(Boolean)
    .join('\n\n');
}

function normalizeAction(action) {
  if (!action || typeof action !== 'object') return null;

  const cleanAction = cleanText(action.action);
  const successSignal = cleanText(action.successSignal);

  if (!cleanAction) return null;

  return {
    action: clipText(cleanAction, 130),
    owner: cleanText(action.owner) || '[Owner]',
    deadline: cleanText(action.deadline) || '[Deadline]',
    successSignal: clipText(successSignal || '[Metric]', 105),
  };
}

function getActions(slide) {
  const rawActions = Array.isArray(slide.actions) ? slide.actions : [];
  return rawActions
    .map(normalizeAction)
    .filter(Boolean)
    .slice(0, 6);
}

function addSectionCard(requests, slideId, slideIndex, itemIndex, x, y, w, h, section, options = {}) {
  if (!isValidSection(section)) return;

  const cardId = id('card', slideIndex, itemIndex);
  const headingId = id('heading', slideIndex, itemIndex);
  const bodyId = id('body', slideIndex, itemIndex);

  addRect(requests, slideId, cardId, x, y, w, h, {
    shapeType: 'ROUND_RECTANGLE',
    fillColor: options.fillColor || COLORS.white,
    borderColor: options.borderColor || COLORS.border,
    borderWeight: options.borderWeight ?? 0.8,
  });

  addText(
    requests,
    slideId,
    headingId,
    x + 12,
    y + 9,
    w - 24,
    22,
    clipText(section.heading, 70),
    {
      fontSize: options.headingFontSize || 11,
      bold: true,
      color: options.headingColor || COLORS.navy,
      lineSpacing: 100,
      skipIfEmpty: true,
    }
  );

  const bodyText = sectionText(section, options.mode || 'full');
  const bodyFont = fontFor(bodyText, options.bodyFontSize || 8.4, options.minBodyFontSize || 6.8);

  addText(
    requests,
    slideId,
    bodyId,
    x + 12,
    y + 34,
    w - 24,
    h - 42,
    bodyText,
    {
      fontSize: bodyFont,
      color: options.bodyColor || COLORS.slate,
      lineSpacing: options.lineSpacing || 100,
      skipIfEmpty: true,
    }
  );
}

function addSlideHeader(requests, slideId, slideIndex, slide) {
  addText(
    requests,
    slideId,
    id('title', slideIndex, 0),
    36,
    22,
    648,
    27,
    cleanText(slide.title) || `Slide ${slideIndex + 1}`,
    {
      fontSize: 19,
      bold: true,
      color: COLORS.dark,
      lineSpacing: 100,
    }
  );

  addText(
    requests,
    slideId,
    id('subtitle', slideIndex, 0),
    36,
    50,
    430,
    19,
    cleanText(slide.subtitle),
    {
      fontSize: 9.3,
      color: COLORS.gray,
      lineSpacing: 100,
      skipIfEmpty: true,
    }
  );

  const keyMessage = cleanText(slide.keyMessage);

  if (keyMessage) {
    addRect(requests, slideId, id('keybg', slideIndex, 0), 36, 75, 648, 35, {
      shapeType: 'ROUND_RECTANGLE',
      fillColor: COLORS.lightBlue,
      borderColor: 'transparent',
    });

    addText(
      requests,
      slideId,
      id('keymsg', slideIndex, 0),
      48,
      82,
      624,
      23,
      keyMessage,
      {
        fontSize: fontFor(keyMessage, 10, 8),
        bold: true,
        color: COLORS.navy,
        lineSpacing: 100,
        valign: 'MIDDLE',
      }
    );
  }
}

function addCallout(requests, slideId, slideIndex, slide, x, y, w, h, color = COLORS.dark) {
  const callout = cleanText(slide.callout) || cleanText(slide.keyMessage);
  if (!callout) return;

  addRect(requests, slideId, id('callout_bg', slideIndex, 0), x, y, w, h, {
    shapeType: 'ROUND_RECTANGLE',
    fillColor: color,
    borderColor: 'transparent',
  });

  addText(
    requests,
    slideId,
    id('callout_text', slideIndex, 0),
    x + 14,
    y + 7,
    w - 28,
    h - 12,
    callout,
    {
      fontSize: fontFor(callout, 9.5, 7.8),
      bold: true,
      color: COLORS.white,
      lineSpacing: 100,
      valign: 'MIDDLE',
    }
  );
}

function drawBackground(requests, slideId, slideIndex, color = COLORS.bg) {
  addRect(requests, slideId, id('bg', slideIndex, 0), 0, 0, CANVAS.w, CANVAS.h, {
    fillColor: color,
    borderColor: 'transparent',
  });
}

function renderHeroContext(requests, slideId, slideIndex, slide, deck) {
  drawBackground(requests, slideId, slideIndex, COLORS.bg);

  addRect(requests, slideId, id('accent', slideIndex, 0), 0, 0, 14, 405, {
    fillColor: COLORS.navy,
    borderColor: 'transparent',
  });

  addText(
    requests,
    slideId,
    id('deck_label', slideIndex, 0),
    42,
    30,
    420,
    18,
    'MEETING REVIEW',
    {
      fontSize: 8.5,
      bold: true,
      color: COLORS.blue,
      lineSpacing: 100,
    }
  );

  const heroTitle = cleanText(slide.title || deck.meetingTitle) || 'Meeting Review';

  addText(
    requests,
    slideId,
    id('hero_title', slideIndex, 0),
    42,
    55,
    440,
    76,
    heroTitle,
    {
      fontSize: fontFor(heroTitle, 24, 18),
      bold: true,
      color: COLORS.dark,
      lineSpacing: 98,
    }
  );

  addText(
    requests,
    slideId,
    id('hero_subtitle', slideIndex, 0),
    42,
    134,
    430,
    28,
    cleanText(slide.subtitle),
    {
      fontSize: 10.5,
      color: COLORS.gray,
      lineSpacing: 102,
      skipIfEmpty: true,
    }
  );

  const keyMessage = cleanText(slide.keyMessage);

  if (keyMessage) {
    addRect(requests, slideId, id('hero_key_bg', slideIndex, 0), 42, 174, 420, 92, {
      shapeType: 'ROUND_RECTANGLE',
      fillColor: COLORS.lightBlue,
      borderColor: 'transparent',
    });

    addText(
      requests,
      slideId,
      id('hero_key_text', slideIndex, 0),
      58,
      190,
      388,
      62,
      keyMessage,
      {
        fontSize: fontFor(keyMessage, 11.5, 8.8),
        bold: true,
        color: COLORS.navy,
        lineSpacing: 106,
        valign: 'MIDDLE',
      }
    );
  }

  const sections = getSections(slide, 0, 3);

  const rightX = 492;
  const rightW = 188;
  const cardH = sections.length >= 3 ? 78 : sections.length === 2 ? 104 : 130;
  const startY = sections.length >= 3 ? 55 : sections.length === 2 ? 72 : 92;
  const gapY = sections.length >= 3 ? 90 : sections.length === 2 ? 122 : 0;

  sections.forEach((section, i) => {
    addSectionCard(requests, slideId, slideIndex, i, rightX, startY + i * gapY, rightW, cardH, section, {
      fillColor: COLORS.white,
      headingFontSize: 10,
      bodyFontSize: 7.4,
      minBodyFontSize: 6.4,
      mode: 'compact',
      lineSpacing: 96,
    });
  });

  addText(
    requests,
    slideId,
    id('meta', slideIndex, 0),
    42,
    282,
    420,
    28,
    `Meeting: ${cleanText(deck.meetingTitle)}\nDate: ${cleanText(deck.date)}`,
    {
      fontSize: 8.8,
      color: COLORS.gray,
      lineSpacing: 102,
    }
  );

  addCallout(requests, slideId, slideIndex, slide, 42, 326, 638, 44, COLORS.dark);
}

function renderThreeInsightCards(requests, slideId, slideIndex, slide) {
  drawBackground(requests, slideId, slideIndex, COLORS.bg);
  addSlideHeader(requests, slideId, slideIndex, slide);

  const sections = getSections(slide, 0, 4);

  const positionsByCount = {
    1: [[126, 142, 468, 150]],
    2: [[36, 142, 316, 132], [368, 142, 316, 132]],
    3: [[36, 122, 316, 102], [368, 122, 316, 102], [202, 236, 316, 102]],
    4: [[36, 122, 316, 102], [368, 122, 316, 102], [36, 236, 316, 102], [368, 236, 316, 102]],
  };

  const positions = positionsByCount[Math.min(Math.max(sections.length, 1), 4)] || positionsByCount[4];

  sections.forEach((section, i) => {
    addSectionCard(requests, slideId, slideIndex, i, ...positions[i], section, {
      fillColor: i % 2 === 0 ? COLORS.white : COLORS.lightBlue,
      bodyFontSize: 8,
      minBodyFontSize: 6.8,
      mode: 'compact',
    });
  });

  addCallout(requests, slideId, slideIndex, slide, 36, 354, 648, 32, COLORS.navy);
}

function renderTwoColumnTension(requests, slideId, slideIndex, slide) {
  drawBackground(requests, slideId, slideIndex, COLORS.bg);
  addSlideHeader(requests, slideId, slideIndex, slide);

  const sections = getSections(slide, 0, 4);
  const left = sections.slice(0, Math.ceil(sections.length / 2));
  const right = sections.slice(Math.ceil(sections.length / 2));

  addText(requests, slideId, id('left_label', slideIndex, 0), 42, 119, 280, 18, 'Pressure / ambiguity', {
    fontSize: 9.5,
    bold: true,
    color: COLORS.gray,
  });

  addText(requests, slideId, id('right_label', slideIndex, 0), 374, 119, 280, 18, 'Decision / implication', {
    fontSize: 9.5,
    bold: true,
    color: COLORS.gray,
