    renderAnalysisMatrix(requests, slideId, slideIndex, slide);
    return;
  }

  if (layout === 'messaging_lab') {
    renderMessagingLab(requests, slideId, slideIndex, slide);
    return;
  }

  if (layout === 'action_tracker') {
    renderActionTracker(requests, slideId, slideIndex, slide);
    return;
  }

  renderGeneric(requests, slideId, slideIndex, slide);
}

