const raw = items[0]?.json ?? {};

function cleanJsonString(value) {
  let text = String(value ?? '').trim();

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');

  if (first >= 0 && last > first) {
    text = text.slice(first, last + 1);
  }

  return text;
}

function extractReport(input) {
  let candidate = input;

  if (candidate && typeof candidate === 'object' && candidate.output !== undefined) {
    candidate = candidate.output;
  }

  if (Array.isArray(candidate)) {
    candidate = candidate
      .map((item) => {
        if (typeof item === 'string') return item;
        if (item?.text) return item.text;
        if (item?.output) return item.output;
        if (item?.json?.output) return item.json.output;
        return '';
      })
      .filter(Boolean)
      .join('\n');
  }

  if (typeof candidate === 'string') {
    return JSON.parse(cleanJsonString(candidate));
  }

  if (candidate && typeof candidate === 'object') {
    return candidate;
  }

  throw new Error('Cannot extract valid report JSON from AI Agent output.');
}

function safeText(value) {
  if (value === null || value === undefined) return '';

  if (typeof value === 'object') {
    const candidates = [
      value.recommendation,
      value.decision,
      value.question,
      value.risk,
      value.riskOrDependency,
      value.action,
      value.takeaway,
      value.point,
      value.summary,
      value.heading,
      value.theme,
      value.text,
      value.title,
      value.impact,
      value.mitigation,
      value.evidence,
      value.implication,
    ];

    const first = candidates.find((item) => typeof item === 'string' && item.trim());

    if (first) {
      return String(first).replace(/\s+/g, ' ').trim();
    }

    return '';
  }

  return String(value).replace(/\s+/g, ' ').trim();
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function lowerFirst(text) {
  const clean = safeText(text);
  if (!clean) return '';
  return clean.charAt(0).toLowerCase() + clean.slice(1);
}

function formatListItem(item) {
  if (item === null || item === undefined) return '';

  if (typeof item === 'string' || typeof item === 'number') {
    return safeText(item);
  }

  if (typeof item === 'object') {
    const parts = [];

    const mainText =
      item.recommendation ||
      item.decision ||
      item.question ||
      item.risk ||
      item.riskOrDependency ||
      item.action ||
      item.takeaway ||
      item.point ||
      item.summary ||
      item.heading ||
      item.theme ||
      item.text ||
      item.title;

    if (mainText) {
      parts.push(safeText(mainText));
    }

    if (item.status) {
      parts.push(`Status: ${safeText(item.status)}`);
    }

    if (item.whyItMatters) {
      parts.push(`Why it matters: ${safeText(item.whyItMatters)}`);
    }

    if (item.evidence) {
      parts.push(`Evidence: ${safeText(item.evidence)}`);
    }

    if (item.implication) {
      parts.push(`Implication: ${safeText(item.implication)}`);
    }

    if (item.nextStep) {
      parts.push(`Next step: ${safeText(item.nextStep)}`);
    }

    if (item.neededResolution) {
      parts.push(`Needed resolution: ${safeText(item.neededResolution)}`);
    }

    if (item.implementationNote) {
      parts.push(`Implementation note: ${safeText(item.implementationNote)}`);
    }

    if (item.impact) {
      parts.push(`Impact: ${safeText(item.impact)}`);
    }

    if (item.mitigation) {
      parts.push(`Mitigation: ${safeText(item.mitigation)}`);
    }

    return parts.filter(Boolean).join(' ');
  }

  return safeText(item);
}

function buildClosingSummary(report) {
  const existing = safeText(report.closingSummary);

  if (existing && existing.length >= 80) {
    return existing;
  }

  const meetingTitle = safeText(report.meetingTitle) || 'the meeting';
  const recommendedDirection = safeText(report.proposal?.recommendedDirection);
  const rationale = safeText(report.proposal?.rationale);

  const firstRisk =
    Array.isArray(report.risksAndDependencies) && report.risksAndDependencies.length
      ? report.risksAndDependencies[0]
      : null;

  const firstAction =
    Array.isArray(report.actionPlan) && report.actionPlan.length
      ? report.actionPlan[0]
      : null;

  const riskText = firstRisk
    ? safeText(firstRisk.risk || firstRisk.riskOrDependency || firstRisk.impact)
    : '';

  const actionText = firstAction
    ? safeText(firstAction.action)
    : '';

  const parts = [];

  parts.push(
    `${meetingTitle} established a clearer direction for converting the discussion into a structured execution plan.`
  );

  if (recommendedDirection) {
    parts.push(`The recommended direction is to ${lowerFirst(recommendedDirection)}.`);
  }

  if (rationale) {
    parts.push(`This direction matters because ${lowerFirst(rationale)}.`);
  }

  if (riskText) {
    parts.push(`The main execution risk to manage is ${lowerFirst(riskText)}.`);
  }

  if (actionText) {
    parts.push(`The immediate next step is to ${lowerFirst(actionText)}.`);
  } else {
    parts.push(
      'The immediate next step is to confirm owners, deadlines, and success signals so the proposal can move from discussion to execution.'
    );
  }

  return parts.join(' ');
}

const report = extractReport(raw);

let docText = '';
const ranges = [];

function addSegment(text, type = 'NORMAL_TEXT') {
  const clean = safeText(text);
  if (!clean) return;

  const startIndex = 1 + docText.length;
  docText += clean + '\n\n';
  const endIndex = 1 + docText.length;

  ranges.push({
    startIndex,
    endIndex,
    type,
  });
}

function addHeading(text, level = 1) {
  addSegment(text, level === 1 ? 'HEADING_1' : 'HEADING_2');
}

function addParagraph(text) {
  addSegment(text, 'NORMAL_TEXT');
}

function addLabeledParagraph(label, value) {
  const clean = safeText(value);
  if (!clean) return;
  addParagraph(`${label}: ${clean}`);
}

function addBulletList(items) {
  asArray(items).forEach((item) => {
    const text = formatListItem(item);
    if (!text) return;
    addParagraph(`• ${text}`);
  });
}

addSegment(report.reportTitle || `Meeting Report: ${report.meetingTitle || 'Untitled Meeting'}`, 'TITLE');

