  addParagraph(`Deadline: ${safeText(action.deadline) || '[Deadline]'}`);
  addParagraph(`Success signal: ${safeText(action.successSignal) || '[Metric]'}`);

  if (action.rationale) {
    addLabeledParagraph('Rationale', action.rationale);
  }

  if (action.dependency) {
    addLabeledParagraph('Dependency', action.dependency);
  }
});

addHeading('7. Closing Summary', 1);
addParagraph(buildClosingSummary(report));

const requests = [
  {
    insertText: {
      location: {
        index: 1,
      },
      text: docText,
    },
  },
];

for (const range of ranges) {
  if (range.endIndex <= range.startIndex) continue;

  requests.push({
    updateParagraphStyle: {
      range: {
        startIndex: range.startIndex,
        endIndex: range.endIndex,
      },
      paragraphStyle: {
        namedStyleType: range.type,
      },
      fields: 'namedStyleType',
    },
  });

  if (range.type === 'TITLE') {
    requests.push({
      updateTextStyle: {
        range: {
          startIndex: range.startIndex,
          endIndex: range.endIndex,
        },
        textStyle: {
          bold: true,
          fontSize: {
            magnitude: 20,
            unit: 'PT',
          },
        },
        fields: 'bold,fontSize',
      },
    });
  }

  if (range.type === 'HEADING_1') {
    requests.push({
      updateTextStyle: {
        range: {
          startIndex: range.startIndex,
          endIndex: range.endIndex,
        },
        textStyle: {
          bold: true,
          fontSize: {
            magnitude: 15,
            unit: 'PT',
          },
        },
        fields: 'bold,fontSize',
      },
    });
  }

  if (range.type === 'HEADING_2') {
    requests.push({
      updateTextStyle: {
        range: {
          startIndex: range.startIndex,
          endIndex: range.endIndex,
        },
        textStyle: {
          bold: true,
          fontSize: {
            magnitude: 12,
            unit: 'PT',
          },
        },
        fields: 'bold,fontSize',
      },
    });
  }
}

return [
  {
    json: {
      reportTitle: safeText(report.reportTitle),
      meetingTitle: safeText(report.meetingTitle),
      closingSummaryUsed: buildClosingSummary(report),
      batchUpdateBody: {
        requests,
      },
    },
  },
];

const raw = items[0]?.json ?? {};

function cleanJsonString(value) {
  let text = String(value ?? '').trim();

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');

  if (first >= 0 && last > first) {
    text = text.slice(first, last + 1);
  }

  return text;
}

function extractJson(input) {
  let candidate = input;

  if (candidate && typeof candidate === 'object' && candidate.output !== undefined) {
    candidate = candidate.output;
  }

  if (Array.isArray(candidate)) {
    candidate = candidate
      .map((item) => {
        if (typeof item === 'string') return item;
        if (item?.text) return item.text;
        if (item?.output) return item.output;
        if (item?.json?.output) return item.json.output;
        return '';
      })
      .filter(Boolean)
      .join('\n');
  }

  if (typeof candidate === 'string') {
    return JSON.parse(cleanJsonString(candidate));
  }

  if (candidate && typeof candidate === 'object') {
    return candidate;
  }

  throw new Error('Cannot extract valid JSON from Meeting Analysis Core output.');
}

function safeText(value) {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/\r?\n|\r/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function ensureArray(value) {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined || value === '') return [];
  return [value];
}

function normalizeStringArray(value) {
  return ensureArray(value).map(safeText).filter(Boolean);
}

function enumValue(value, allowed, fallback) {
  const text = safeText(value);
  return allowed.includes(text) ? text : fallback;
}

function wordCount(text) {
  const clean = safeText(text);
  if (!clean) return 0;
  return clean.split(/\s+/).length;
}

function hasGenericFallback(text) {
  const t = safeText(text).toLowerCase();

  const banned = [
    'specific detail was not fully defined',
    'confirm the missing detail',
    'follow-up area',
    'key discussion point',
    'referenced in the meeting discussion',
    'improve collaboration',
    'optimize strategy',
    'drive impact',
  ];

  return banned.some((phrase) => t.includes(phrase));
}

const core = extractJson(raw);

const requiredTopFields = [
  'meetingInfo',
  'contextSnapshot',
  'executiveBrief',
  'keyThemes',
  'decisions',
  'openQuestions',
  'risksAndDependencies',
  'proposal',
  'messagingGuidance',
  'actionPlan',
  'evidenceMap',
  'contentGuardrails',
  'qualityNotes',
];

const missingFields = requiredTopFields.filter((field) => core[field] === undefined);

if (missingFields.length > 0) {
  throw new Error(`Core analysis missing required fields: ${missingFields.join(', ')}`);
}

const normalizedCore = {
  schemaVersion: 'meeting-analysis-core-v2.1',

  meetingInfo: {
    title: safeText(core.meetingInfo?.title),
    date: safeText(core.meetingInfo?.date),
    participants: safeText(core.meetingInfo?.participants),
    meetingId: safeText(core.meetingInfo?.meetingId),
    gist: safeText(core.meetingInfo?.gist),
    purpose: safeText(core.meetingInfo?.purpose),
    meetingType: enumValue(
      core.meetingInfo?.meetingType,
      [
        'Strategy',
        'Planning',
        'Review',
        'Operations',
        'Incident Review',
        'Sales',
        'Product',
        'Marketing',
        'Engineering',
        'HR',
        'Finance',
        'Customer Support',
        'Other',
      ],
      'Other'
    ),
  },

  contextSnapshot: {
    businessContext: safeText(core.contextSnapshot?.businessContext),
    mainObjective: safeText(core.contextSnapshot?.mainObjective),
    stakeholdersOrFunctions: safeText(core.contextSnapshot?.stakeholdersOrFunctions),
    discussionScope: safeText(core.contextSnapshot?.discussionScope),
    whyThisMeetingMatters: safeText(core.contextSnapshot?.whyThisMeetingMatters),
  },

  executiveBrief: {
    oneSentenceThesis: safeText(core.executiveBrief?.oneSentenceThesis),
    leadershipNarrative: safeText(core.executiveBrief?.leadershipNarrative),
    topTakeaways: ensureArray(core.executiveBrief?.topTakeaways)
      .map((item) => ({
        takeaway: safeText(item.takeaway),
        whyItMatters: safeText(item.whyItMatters),
        evidence: safeText(item.evidence),
      }))
      .filter((item) => item.takeaway || item.whyItMatters || item.evidence),
  },

  keyThemes: ensureArray(core.keyThemes)
    .map((item) => ({
      theme: safeText(item.theme),
      priorityLevel: enumValue(item.priorityLevel, ['High', 'Medium', 'Low'], 'Medium'),
      summary: safeText(item.summary),
      detailedAnalysis: safeText(item.detailedAnalysis),
      evidence: safeText(item.evidence),
      implication: safeText(item.implication),
      decisionRelevance: safeText(item.decisionRelevance),
      riskOrTradeoff: safeText(item.riskOrTradeoff),
      recommendedFollowUp: safeText(item.recommendedFollowUp),
      slideUse: safeText(item.slideUse),
      reportUse: safeText(item.reportUse),
    }))
    .filter((item) => item.theme && (item.summary || item.detailedAnalysis)),

  decisions: ensureArray(core.decisions)
    .map((item) => ({
      decision: safeText(item.decision),
      status: enumValue(item.status, ['Confirmed', 'Proposed', 'Decision Needed'], 'Decision Needed'),
      evidence: safeText(item.evidence),
      implication: safeText(item.implication),
      nextStep: safeText(item.nextStep),
    }))
    .filter((item) => item.decision),

  openQuestions: ensureArray(core.openQuestions)
    .map((item) => ({
      question: safeText(item.question),
      whyItMatters: safeText(item.whyItMatters),
      neededResolution: safeText(item.neededResolution),
      suggestedOwner: safeText(item.suggestedOwner) || '[Owner]',
    }))
    .filter((item) => item.question),

  risksAndDependencies: ensureArray(core.risksAndDependencies)
    .map((item) => ({
      riskOrDependency: safeText(item.riskOrDependency),
      type: enumValue(item.type, ['Risk', 'Dependency', 'Tradeoff'], 'Risk'),
      impact: safeText(item.impact),
      rootCauseOrDriver: safeText(item.rootCauseOrDriver),
      mitigation: safeText(item.mitigation),
      relatedTheme: safeText(item.relatedTheme),
    }))
    .filter((item) => item.riskOrDependency),

  proposal: {
    recommendedDirection: safeText(core.proposal?.recommendedDirection),
    proposalNarrative: safeText(core.proposal?.proposalNarrative),
    rationale: safeText(core.proposal?.rationale),
    expectedImpact: safeText(core.proposal?.expectedImpact),
    recommendations: ensureArray(core.proposal?.recommendations)
      .map((item) => ({
        recommendation: safeText(item.recommendation),
        whyItMatters: safeText(item.whyItMatters),
        evidence: safeText(item.evidence),
        implementationNote: safeText(item.implementationNote),
      }))
      .filter((item) => item.recommendation),
  },

  messagingGuidance: {
    currentSignal: safeText(core.messagingGuidance?.currentSignal),
    recommendedNarrative: safeText(core.messagingGuidance?.recommendedNarrative),
    proofPoints: normalizeStringArray(core.messagingGuidance?.proofPoints),
    messagingRisksToAvoid: normalizeStringArray(core.messagingGuidance?.messagingRisksToAvoid),
    suggestedLanguage: normalizeStringArray(core.messagingGuidance?.suggestedLanguage),
  },

  actionPlan: ensureArray(core.actionPlan)
    .map((item) => ({
      action: safeText(item.action),
      owner: safeText(item.owner) || '[Owner]',
      deadline: safeText(item.deadline) || '[Deadline]',
      successSignal: safeText(item.successSignal) || '[Metric]',
      sourceTheme: safeText(item.sourceTheme),
      rationale: safeText(item.rationale),
      dependency: safeText(item.dependency),
    }))
    .filter((item) => item.action),

  evidenceMap: ensureArray(core.evidenceMap)
    .map((item) => ({
      point: safeText(item.point),
      supportingEvidence: safeText(item.supportingEvidence),
      usedFor: enumValue(
        item.usedFor,
        ['Theme', 'Decision', 'Risk', 'Proposal', 'Action', 'Messaging'],
        'Theme'
      ),
    }))
    .filter((item) => item.point || item.supportingEvidence),

  contentGuardrails: {
    supportedClaims: normalizeStringArray(core.contentGuardrails?.supportedClaims),
    doNotClaim: normalizeStringArray(core.contentGuardrails?.doNotClaim),
    missingInformation: normalizeStringArray(core.contentGuardrails?.missingInformation),
    lowConfidenceAreas: normalizeStringArray(core.contentGuardrails?.lowConfidenceAreas),
  },

  downstreamBrief: {
    slideBrief: safeText(core.downstreamBrief?.slideBrief),
    reportBrief: safeText(core.downstreamBrief?.reportBrief),
    recommendedDeckAngle: safeText(core.downstreamBrief?.recommendedDeckAngle),
    recommendedReportAngle: safeText(core.downstreamBrief?.recommendedReportAngle),
    mustUseThemes: normalizeStringArray(core.downstreamBrief?.mustUseThemes),
    mustAvoidClaims: normalizeStringArray(core.downstreamBrief?.mustAvoidClaims),
  },

  qualityNotes: {
    confidenceLevel: enumValue(core.qualityNotes?.confidenceLevel, ['High', 'Medium', 'Low'], 'Medium'),
    overallAssessment: safeText(core.qualityNotes?.overallAssessment),
    recommendedDownstreamUse: safeText(core.qualityNotes?.recommendedDownstreamUse),
  },
};

const qualityWarnings = [];

if (normalizedCore.keyThemes.length < 6) {
  qualityWarnings.push(`Expected at least 6 key themes, got ${normalizedCore.keyThemes.length}.`);
}

if (normalizedCore.actionPlan.length < 5) {
  qualityWarnings.push(`Expected at least 5 actions, got ${normalizedCore.actionPlan.length}.`);
}

if (normalizedCore.evidenceMap.length < 8) {
  qualityWarnings.push(`Expected at least 8 evidence items, got ${normalizedCore.evidenceMap.length}.`);
}

if (!normalizedCore.proposal.recommendedDirection) {
  qualityWarnings.push('Missing proposal.recommendedDirection.');
}

if (!normalizedCore.executiveBrief.leadershipNarrative) {
  qualityWarnings.push('Missing executiveBrief.leadershipNarrative.');
}

if (!normalizedCore.contentGuardrails.doNotClaim.length) {
  qualityWarnings.push('Missing contentGuardrails.doNotClaim.');
}

if (!normalizedCore.downstreamBrief.slideBrief || !normalizedCore.downstreamBrief.reportBrief) {
  qualityWarnings.push('Missing downstreamBrief.slideBrief or downstreamBrief.reportBrief.');
}

const shortThemeCount = normalizedCore.keyThemes.filter(
  (theme) => wordCount(theme.summary) < 45 || wordCount(theme.detailedAnalysis) < 75
).length;

if (shortThemeCount > 0) {
  qualityWarnings.push(`${shortThemeCount} key theme(s) may be too short.`);
}

const genericThemeCount = normalizedCore.keyThemes.filter(
  (theme) =>
    hasGenericFallback(theme.summary) ||
    hasGenericFallback(theme.detailedAnalysis) ||
    hasGenericFallback(theme.implication)
).length;

if (genericThemeCount > 0) {
  qualityWarnings.push(`${genericThemeCount} key theme(s) contain generic or fallback wording.`);
}

const readyForDownstream =
  normalizedCore.keyThemes.length >= 6 &&
  normalizedCore.actionPlan.length >= 5 &&
  normalizedCore.evidenceMap.length >= 8 &&
  Boolean(normalizedCore.proposal.recommendedDirection) &&
  Boolean(normalizedCore.downstreamBrief.slideBrief) &&
  Boolean(normalizedCore.downstreamBrief.reportBrief) &&
  genericThemeCount === 0;

if (qualityWarnings.length > 0) {
  normalizedCore.qualityNotes.confidenceLevel =
    normalizedCore.qualityNotes.confidenceLevel === 'High'
      ? 'Medium'
      : normalizedCore.qualityNotes.confidenceLevel;
}

function buildCoreAnalysisSummaryText(core) {
  const lines = [];

  lines.push(`Meeting: ${core.meetingInfo.title}`);
  lines.push(`Date: ${core.meetingInfo.date}`);
  lines.push(`Participants: ${core.meetingInfo.participants}`);
  lines.push(`Purpose: ${core.meetingInfo.purpose}`);
  lines.push('');

  lines.push('Executive Thesis:');
  lines.push(core.executiveBrief.oneSentenceThesis);
  lines.push('');

  lines.push('Leadership Narrative:');
  lines.push(core.executiveBrief.leadershipNarrative);
  lines.push('');

  lines.push('Recommended Deck Angle:');
  lines.push(core.downstreamBrief.recommendedDeckAngle);
  lines.push('');

  lines.push('Recommended Report Angle:');
  lines.push(core.downstreamBrief.recommendedReportAngle);
  lines.push('');

  lines.push('Key Themes:');
  core.keyThemes.forEach((theme, index) => {
    lines.push(`${index + 1}. ${theme.theme} [${theme.priorityLevel}]`);
    lines.push(`Summary: ${theme.summary}`);
    lines.push(`Analysis: ${theme.detailedAnalysis}`);
    lines.push(`Evidence: ${theme.evidence}`);
    lines.push(`Implication: ${theme.implication}`);
    lines.push(`Follow-up: ${theme.recommendedFollowUp}`);
    lines.push('');
  });

  lines.push('Proposal:');
  lines.push(core.proposal.recommendedDirection);
  lines.push(core.proposal.proposalNarrative);
  lines.push('');

  lines.push('Actions:');
  core.actionPlan.forEach((action, index) => {
    lines.push(`${index + 1}. ${action.action}`);
    lines.push(`Owner: ${action.owner}`);
    lines.push(`Deadline: ${action.deadline}`);
    lines.push(`Success signal: ${action.successSignal}`);
    lines.push(`Rationale: ${action.rationale}`);
    lines.push('');
  });

  lines.push('Do Not Claim:');
  core.contentGuardrails.doNotClaim.forEach((item) => lines.push(`- ${item}`));

  return lines.join('\n');
}

function buildDownstreamCoreText(core) {
  return [
    `Meeting title: ${core.meetingInfo.title}`,
    `Meeting type: ${core.meetingInfo.meetingType}`,
    `Purpose: ${core.meetingInfo.purpose}`,
    '',
    `Deck angle: ${core.downstreamBrief.recommendedDeckAngle}`,
    `Report angle: ${core.downstreamBrief.recommendedReportAngle}`,
    '',
    `Slide brief: ${core.downstreamBrief.slideBrief}`,
    '',
    `Report brief: ${core.downstreamBrief.reportBrief}`,
    '',
    `Executive thesis: ${core.executiveBrief.oneSentenceThesis}`,
    '',
    `Must-use themes: ${core.downstreamBrief.mustUseThemes.join('; ')}`,
    '',
    `Proposal direction: ${core.proposal.recommendedDirection}`,
    '',
    `Must-avoid claims: ${core.downstreamBrief.mustAvoidClaims.join('; ')}`,
  ].join('\n');
}

const coreAnalysisJson = JSON.stringify(normalizedCore);
const coreAnalysisSummaryText = buildCoreAnalysisSummaryText(normalizedCore);
const downstreamCoreText = buildDownstreamCoreText(normalizedCore);

return [
  {
    json: {
      ...normalizedCore,
      qualityWarnings,
      qualityGate: {
        readyForDownstream,
        status: readyForDownstream ? 'PASS' : 'REVIEW',
      },
      coreStats: {
        keyThemeCount: normalizedCore.keyThemes.length,
        decisionCount: normalizedCore.decisions.length,
        openQuestionCount: normalizedCore.openQuestions.length,
        riskDependencyCount: normalizedCore.risksAndDependencies.length,
        actionCount: normalizedCore.actionPlan.length,
        evidenceCount: normalizedCore.evidenceMap.length,
        warningCount: qualityWarnings.length,
      },
      coreAnalysisJson,
      coreAnalysisSummaryText,
      downstreamCoreText,
    },
  },
];
